```js
class FakePaymentProvider {
  constructor() {
    this.calls = [];
    this.responses = [];
    this.defaultResponse = { id: 're_test_default', status: 'succeeded' };
  }
  enqueueResponse(response) { this.responses.push(response); return this; }
  async refund(payload, options = {}) {
    this.calls.push({ payload, options });
    const next = this.responses.length ? this.responses.shift() : this.defaultResponse;
    if (next instanceof Error) throw next;
    return { amount: payload.amount, currency: payload.currency, ...next };
  }
}
module.exports = { FakePaymentProvider };
```

