const { refundPayment } = require('../../src/payments/refund');
const { FakePaymentProvider } = require('../fakes/fakePaymentProvider');

describe('refundPayment', () => {
  let provider;
  beforeEach(() => { provider = new FakePaymentProvider(); });

  it('refunds the full amount and returns the provider refund', async () => {
    provider.enqueueResponse({ id: 're_123', status: 'succeeded' });
    const result = await refundPayment(
      { paymentId: 'pay_123', amount: 2500, currency: 'usd' },
      { provider }
    );
    expect(result).toMatchObject({ providerRefundId: 're_123', status: 'succeeded' });
    expect(provider.calls).toHaveLength(1);
    expect(provider.calls[0].payload).toMatchObject({ paymentId: 'pay_123', amount: 2500, currency: 'usd' });
  });

  it('passes a partial refund amount through unchanged', async () => {
    provider.enqueueResponse({ id: 're_124', status: 'succeeded' });
    await refundPayment({ paymentId: 'pay_123', amount: 500, currency: 'usd' }, { provider });
    expect(provider.calls[0].payload.amount).toBe(500);
  });

  it('surfaces a declined refund as an error and never reports success', async () => {
    provider.enqueueResponse(new Error('card_declined'));
    await expect(
      refundPayment({ paymentId: 'pay_123', amount: 2500, currency: 'usd' }, { provider })
    ).rejects.toThrow(/declined|refund/i);
  });

  it('does not retry a timed-out refund (no double refund)', async () => {
    provider.enqueueResponse(new Error('ETIMEDOUT'));
    await expect(
      refundPayment({ paymentId: 'pay_123', amount: 2500, currency: 'usd' }, { provider })
    ).rejects.toBeTruthy();
    expect(provider.calls).toHaveLength(1);
  });

  it('sends a stable idempotency key for the same refund request', async () => {
    provider.enqueueResponse({ id: 're_125', status: 'succeeded' }).enqueueResponse({ id: 're_125', status: 'succeeded' });
    const req = { paymentId: 'pay_123', amount: 2500, currency: 'usd' };
    await refundPayment(req, { provider });
    await refundPayment(req, { provider });
    const [first, second] = provider.calls.map(c => c.options.idempotencyKey);
    expect(first).toBeTruthy();
    expect(second).toBe(first);
  });
});
```

