**`test/payments/fakeProvider.js`**

```js
'use strict';

/**
 * In-memory stand-in for the payment provider.
 * Records every call; never touches the network.
 */
class FakePaymentProvider {
  constructor() {
    this.calls = [];
    this.refunds = new Map();
    this.nextResult = null;   // set to override the next response
    this.nextError = null;    // set to make the next call reject
  }

  async refund(request) {
    this.calls.push(request);

    if (this.nextError) {
      const err = this.nextError;
      this.nextError = null;
      throw err;
    }

    const result =
      this.nextResult || {
        id: `re_fake_${this.calls.length}`,
        status: 'succeeded',
        amount: request.amount,
        currency: 'usd',
      };
    this.nextResult = null;

    this.refunds.set(result.id, { ...request, ...result });
    return result;
  }

  reset() {
    this.calls = [];
    this.refunds.clear();
    this.nextResult = null;
    this.nextError = null;
  }
}

module.exports = { FakePaymentProvider };
```

**`test/payments/refund.test.js`**

