'use strict';

// No outbound HTTP from the test suite, ever.
const nock = require('nock');
beforeAll(() => nock.disableNetConnect());
afterAll(() => nock.enableNetConnect());

const { FakePaymentProvider } = require('./fakeProvider');

// Inject the fake instead of the real provider module.
const fakeProvider = new FakePaymentProvider();
jest.mock('../../src/payments/provider', () => fakeProvider);

const { refundPayment } = require('../../src/payments/refund');

describe('refundPayment', () => {
  beforeEach(() => fakeProvider.reset());

  test('sends the expected request to the provider', async () => {
    const result = await refundPayment({
      paymentId: 'pay_123',
      amountCents: 2500,
      reason: 'customer_request',
    });

    expect(fakeProvider.calls).toHaveLength(1);
    expect(fakeProvider.calls[0]).toMatchObject({
      paymentId: 'pay_123',
      amount: 2500,
      reason: 'customer_request',
    });
    expect(fakeProvider.calls[0].idempotencyKey).toEqual(expect.any(String));
    expect(result).toMatchObject({ status: 'succeeded', amount: 2500 });
  });

  test('sends an idempotency key that is stable per refund request', async () => {
    const request = { paymentId: 'pay_123', amountCents: 2500 };
    await refundPayment(request);
    const firstKey = fakeProvider.calls[0].idempotencyKey;

    // Same logical request repeated -> same key, so the provider dedupes it.
    await refundPayment(request);
    expect(fakeProvider.calls[1].idempotencyKey).toBe(firstKey);
  });

  test('refunds the full amount when no amount is given', async () => {
    await refundPayment({ paymentId: 'pay_123' });
    expect(fakeProvider.calls[0].amount).toBeUndefined();
  });

  test.each([0, -1, -2500, 12.5, NaN])(
    'rejects an invalid amount (%p) without calling the provider',
    async (amountCents) => {
      await expect(
        refundPayment({ paymentId: 'pay_123', amountCents })
      ).rejects.toThrow();
      expect(fakeProvider.calls).toHaveLength(0);
    }
  );

  test.each([undefined, null, ''])(
    'rejects a missing payment id (%p) without calling the provider',
    async (paymentId) => {
      await expect(
        refundPayment({ paymentId, amountCents: 2500 })
      ).rejects.toThrow();
      expect(fakeProvider.calls).toHaveLength(0);
    }
  );

  test('surfaces a provider error and does not retry', async () => {
    fakeProvider.nextError = Object.assign(new Error('card_declined'), {
      statusCode: 402,
    });

    await expect(
      refundPayment({ paymentId: 'pay_123', amountCents: 2500 })
    ).rejects.toThrow(/card_declined/);

    // Exactly one attempt: a blind retry can double-refund on a timeout.
    expect(fakeProvider.calls).toHaveLength(1);
  });

  test('does not treat a non-succeeded refund as success', async () => {
    fakeProvider.nextResult = {
      id: 're_pending',
      status: 'pending',
      amount: 2500,
      currency: 'usd',
    };

    const result = await refundPayment({
      paymentId: 'pay_123',
      amountCents: 2500,
    });

    // Shape is whatever the function returns; assert we don't silently
    // report success for a non-succeeded status.
    expect(result.status).not.toBe('succeeded');
  });
});
```

