// src/billing/due.test.js
const { dueDate } = require('./due');

// Fixed dates at local noon. Noon is far from midnight and the windows below
// contain no DST switch, so these expectations hold in every timezone.
const atNoon = (year, month, day) => new Date(year, month - 1, day, 12, 0, 0, 0);

describe('dueDate', () => {
  beforeEach(() => {
    // dueDate must depend only on its argument, never on the clock.
    jest.useFakeTimers();
    jest.setSystemTime(atNoon(2025, 6, 1));
  });

  afterEach(() => {
    jest.useRealTimers();
  });

  it('is 30 days after the issue date', () => {
    expect(dueDate(atNoon(2024, 1, 15))).toEqual(atNoon(2024, 2, 14));
  });

  it('rolls over the end of a month in a leap year', () => {
    expect(dueDate(atNoon(2024, 1, 31))).toEqual(atNoon(2024, 3, 1));
  });

  it('rolls over the end of a non-leap-year month', () => {
    expect(dueDate(atNoon(2023, 1, 31))).toEqual(atNoon(2023, 3, 2));
  });

  it('rolls over the end of a year', () => {
    expect(dueDate(atNoon(2023, 12, 15))).toEqual(atNoon(2024, 1, 14));
  });

  it('counts the leap day', () => {
    expect(dueDate(atNoon(2024, 2, 1))).toEqual(atNoon(2024, 3, 2));
  });

  it('gives the same answer whatever today is', () => {
    const issue = atNoon(2024, 1, 15);
    const first = dueDate(issue);

    jest.setSystemTime(new Date(2024, 11, 31, 23, 59, 59, 999));
    expect(dueDate(issue)).toEqual(first);
  });

  it('does not modify the issue date it is given', () => {
    const issue = atNoon(2024, 1, 15);
    dueDate(issue);
    expect(issue).toEqual(atNoon(2024, 1, 15));
  });

  it('returns an invalid date for an invalid issue date', () => {
    expect(dueDate(new Date(NaN)).getTime()).toBeNaN();
  });
