/**
 * Tests for dueDate(issueDate): an invoice is due 30 calendar days after issue.
 *
 * Every test passes an explicit, fixed issue date and compares against a
 * hard-coded expected date. Nothing here reads the real clock.
 *
 * The previous draft was:
 *   expect(dueDate(new Date())).toEqual(addDays(new Date(), 30))
 * It called new Date() twice, so actual and expected were computed from two
 * different instants. Near midnight the second call lands on the next day and
 * the assertion fails at random. It also built the expectation with the
 * production addDays() helper, so a bug in that helper would cancel itself out.
 *
 * No fake timers are needed: dueDate() takes the date as an argument and does
 * not read the clock itself. If that ever changes, freeze the clock here.
 *
 * Times are local noon / mid-morning rather than midnight so the tests are not
 * sensitive to clock changes. Expected values are calendar days: if dueDate
 * ever switches to millisecond arithmetic (30 * 24 * 60 * 60 * 1000), the
 * leap-day case below will fail in timezones that start DST in March — that
 * would be a real bug in dueDate, not in the test.
 */
const { dueDate } = require('./due');

describe('dueDate', () => {
  it('returns a date 30 calendar days after the issue date', () => {
    const issued = new Date(2024, 0, 15, 9, 0, 0); // 15 Jan 2024, 09:00
    expect(dueDate(issued)).toEqual(new Date(2024, 1, 14, 9, 0, 0)); // 14 Feb 2024
  });

  it('keeps the time of day of the issue date', () => {
    const issued = new Date(2024, 0, 15, 23, 59, 59, 999);
    expect(dueDate(issued)).toEqual(new Date(2024, 1, 14, 23, 59, 59, 999));
  });

  it('rolls over a month boundary in a leap year', () => {
    // 31 Jan 2024 + 30 days = 1 Mar 2024 (February has 29 days)
    expect(dueDate(new Date(2024, 0, 31, 12, 0, 0))).toEqual(new Date(2024, 2, 1, 12, 0, 0));
  });

  it('rolls over a month boundary in a non-leap year', () => {
    // 31 Jan 2023 + 30 days = 2 Mar 2023 (February has 28 days)
    expect(dueDate(new Date(2023, 0, 31, 12, 0, 0))).toEqual(new Date(2023, 2, 2, 12, 0, 0));
  });

  it('handles an issue date on a leap day', () => {
    // 29 Feb 2024 + 30 days = 30 Mar 2024
    expect(dueDate(new Date(2024, 1, 29, 12, 0, 0))).toEqual(new Date(2024, 2, 30, 12, 0, 0));
  });

  it('rolls over a year boundary', () => {
    // 31 Dec 2024 + 30 days = 30 Jan 2025
    expect(dueDate(new Date(2024, 11, 31, 12, 0, 0))).toEqual(new Date(2025, 0, 30, 12, 0, 0));
  });

  it('does not mutate the issue date it is given', () => {
    const issued = new Date(2024, 0, 15, 9, 0, 0);
    dueDate(issued);
    expect(issued).toEqual(new Date(2024, 0, 15, 9, 0, 0));
