describe('dueDate', () => {
  it('is due 30 days after the issue date', () => {
    // Fixed issue date, local noon: avoids midnight and DST/timezone edges.
    const issueDate = new Date(2024, 0, 15, 12, 0, 0, 0); // 15 Jan 2024
