```js
// test/fakes/paymentProvider.js
// Same interface as the real payment client. Talks to nothing. No real data.
function createFakePaymentProvider() {
  const calls = [];
  let nextResult = { id: 're_test_1', status: 'succeeded', amount: 0, currency: 'USD' };

  return {
    calls,
    /** Make the next provider call return this value, throw, or time out. */
    willReturn(result) { nextResult = result; },
    willThrow(err) { nextResult = { __throw: err }; },
    willTimeOut() { nextResult = { __timeout: true }; },

    refunds: {
      async create(params) {
        calls.push({ method: 'refunds.create', params });
        if (nextResult.__timeout) throw new Error('ETIMEDOUT');
        if (nextResult.__throw) throw nextResult.__throw;
        return { ...nextResult, amount: params.amount, currency: params.currency };
      },
    },
  };
}

module.exports = { createFakePaymentProvider };
