```js
// test/fakes/fakePaymentProvider.js
export function createFakePaymentProvider({ outcomes = [] } = {}) {
  const calls = [];
  return {
    calls,
    async refund(paymentId, amount, { idempotencyKey } = {}) {
      calls.push({ paymentId, amount, idempotencyKey });
      const next = outcomes.shift() ?? { ok: true, id: `re_test_${calls.length}` };
      if (!next.ok) {
        const err = new Error(next.message ?? 'provider error');
        err.code = next.code ?? 'provider_error';
        throw err;
      }
      return { id: next.id, status: 'succeeded', amount };
    },
  };
}
```

