'use strict';

const { dueDate } = require('./due');

/**
 * Build dates from local components on purpose.
 * Do NOT use new Date('2024-01-15'): a date-only ISO string is parsed as UTC
 * midnight and lands on the previous day in any negative-offset timezone.
 * Default time 10:30 so a DST-sized shift cannot silently change the date.
 */
function localDate(year, month, day, hours = 10, minutes = 30) {
  return new Date(year, month - 1, day, hours, minutes, 0, 0);
}

describe('dueDate', () => {
  test('is exactly 30 calendar days after the issue date', () => {
    const issued = localDate(2024, 1, 15);                   // Mon 15 Jan 2024, 10:30 local
    expect(dueDate(issued)).toEqual(localDate(2024, 2, 14)); // Wed 14 Feb 2024, 10:30 local
  });

  test('preserves the time of day of the issue date', () => {
    const due = dueDate(localDate(2024, 1, 15, 23, 45));
    expect([due.getHours(), due.getMinutes()]).toEqual([23, 45]);
  });

  test('does not mutate the issue date it is given', () => {
    const issued = localDate(2024, 1, 15);
    const before = issued.getTime();
    dueDate(issued);
    expect(issued.getTime()).toBe(before);
  });

  describe('month and year boundaries', () => {
    test.each([
      ['31 Jan 2024 (leap year)', localDate(2024, 1, 31), localDate(2024, 3, 1)],
      ['31 Jan 2023 (non-leap)',  localDate(2023, 1, 31), localDate(2023, 3, 2)],
      ['29 Feb 2024 (leap day)',  localDate(2024, 2, 29), localDate(2024, 3, 30)],
      ['28 Feb 2023',             localDate(2023, 2, 28), localDate(2023, 3, 30)],
      ['31 Dec 2024 (year end)',  localDate(2024, 12, 31), localDate(2025, 1, 30)],
      ['1 Jan 2025',              localDate(2025, 1, 1),  localDate(2025, 1, 31)],
    ])('%s rolls over correctly', (_name, issued, expected) => {
      expect(dueDate(issued)).toEqual(expected);
    });
  });

  // These two only bite when the suite runs in a timezone that observes DST.
  // The test script pins TZ so this is deterministic on every machine.
  describe('across daylight-saving transitions', () => {
    test.each([
      ['spring forward', localDate(2024, 3, 1),   localDate(2024, 3, 31)],
      ['autumn fall back', localDate(2024, 10, 15), localDate(2024, 11, 14)],
    ])('%s stays on the calendar day, not 30x24h of milliseconds', (_name, issued, expected) => {
      expect(dueDate(issued)).toEqual(expected);
    });
  });
});
```

