```js
'use strict';

// In-memory stand-in for the payment provider. No network, no real charges.
function createFakePaymentProvider({ mode = 'success', refundId = 're_test_123' } = {}) {
  const calls = { refundsCreate: [] };

  return {
    calls,
    refunds: {
      async create(params) {
        calls.refundsCreate.push(params);

        if (mode === 'decline') {
          const err = new Error('card_declined');
          err.code = 'card_declined';
          err.statusCode = 402;
          throw err;
        }
        if (mode === 'timeout') {
          const err = new Error('ETIMEDOUT');
          err.code = 'ETIMEDOUT';
          throw err;
        }
        return { id: refundId, status: 'succeeded', amount: params.amount, currency: params.currency };
      },
    },
  };
}

module.exports = { createFakePaymentProvider };
```

