The root cause: `new Date()` is called twice, so it returns two different instants. If the clock crosses midnight between the two calls, `dueDate(now₁)` is `now₁ + 30d` while the expectation is `now₂ + 30d` — one day apart. The test also depends on the machine's timezone and on DST, so it can fail for reasons unrelated to the change.

## Corrected test file

```js
// src/billing/due.test.js
const { dueDate } = require('./due');

// Build dates from local components at midday. Midday keeps us clear of
// DST transitions and timezone offsets that can shift the calendar day.
const atNoon = (year, monthIndex, day) => new Date(year, monthIndex, day, 12, 0, 0, 0);

describe('dueDate', () => {
  test('is 30 days after the issue date', () => {
    const issueDate = atNoon(2024, 0, 15); // 2024-01-15 12:00 local

    expect(dueDate(issueDate)).toEqual(atNoon(2024, 1, 14)); // 2024-02-14 12:00 local
  });

  test('handles a month boundary', () => {
    const issueDate = atNoon(2024, 0, 31); // Jan 31

    expect(dueDate(issueDate)).toEqual(atNoon(2024, 2, 1)); // Mar 1 (2024 is a leap year)
  });

  test('handles a leap-day issue date', () => {
    const issueDate = atNoon(2024, 1, 29); // Feb 29 2024

    expect(dueDate(issueDate)).toEqual(atNoon(2024, 2, 30)); // Mar 30
  });

  test('does not mutate the issue date', () => {
    const issueDate = atNoon(2024, 0, 15);
    const original = issueDate.getTime();

    dueDate(issueDate);

    expect(issueDate.getTime()).toBe(original);
  });
});
```

