```js
'use strict';

const { dueDate } = require('./due');

// Build dates in local time at noon. Noon keeps the test away from DST
// transitions that happen at midnight in some zones, so the test behaves the
// same on any machine. Never build an expectation from `new Date()`: two clock
// reads can straddle midnight and make the test flaky.
const at = (y, m, d) => new Date(y, m - 1, d, 12, 0, 0, 0);

describe('dueDate', () => {
  // Normal case
  it('adds 30 days to a mid-month issue date', () => {
    expect(dueDate(at(2025, 3, 10))).toEqual(at(2025, 4, 9)));
  });

  // Boundaries: short month, leap day, year end, first of the month
  it('adds 30 days across a short month', () => {
    expect(dueDate(at(2025, 1, 31))).toEqual(at(2025, 3, 2));
  });

  it('adds 30 days when a leap day falls inside the window', () => {
    expect(dueDate(at(2024, 2, 1))).toEqual(at(2024, 3, 2));
  });

  it('adds 30 days when the issue date is itself a leap day', () => {
    expect(dueDate(at(2024, 2, 29))).toEqual(at(2024, 3, 30));
  });

  it('adds 30 days across a year boundary', () => {
    expect(dueDate(at(2024, 12, 15))).toEqual(at(2025, 1, 14));
  });

  it('adds 30 days from the first of a 31-day month', () => {
    expect(dueDate(at(2025, 1, 1))).toEqual(at(2025, 1, 31));
  });

  // The function must not modify the date it is handed
  it('does not mutate the issue date', () => {
    const issue = at(2025, 3, 10);
    dueDate(issue);
    expect(issue).toEqual(at(2025, 3, 10));
  });

  // Missing / invalid input
  it('throws a TypeError when no issue date is given', () => {
    expect(() => dueDate()).toThrow(TypeError);
    expect(() => dueDate(null)).toThrow(TypeError);
  });

  it('throws a TypeError for an invalid issue date', () => {
    expect(() => dueDate(new Date('not a date'))).toThrow(TypeError);
    expect(() => dueDate('2025-03-10')).toThrow(TypeError);
  });

  // Regression test for the original flake: the result must not move when the
  // clock crosses midnight. Swap to vi.useFakeTimers() if the repo is on Vitest.
  it('does not depend on the current clock', () => {
    jest.useFakeTimers();
    try {
      jest.setSystemTime(new Date(2025, 2, 10, 23, 59, 59));
      const justBeforeMidnight = dueDate(at(2025, 5, 1));

      jest.setSystemTime(new Date(2025, 2, 11, 0, 0, 1));
      const justAfterMidnight = dueDate(at(2025, 5, 1));

      expect(justBeforeMidnight).toEqual(justAfterMidnight);
      expect(justBeforeMidnight).toEqual(at(2025, 5, 31));
    } finally {
      jest.useRealTimers();
    }
  });
});
```

