// tests/billing/rounding.test.js
const { total } = require("../../src/billing/total");

describe("total() — rounding", () => {
  test("rounds a half-cent up to the next cent", () => {
    // 1.005 as a double is 1.00499999999999989…, so this only passes if
    // rounding happens on the decimal form. That is the regression under test.
    expect(total([{ price: 1.005, qty: 1 }])).toBe("1.01");
  });

  test("rounds half-cents up regardless of the preceding digit", () => {
    expect(total([{ price: 1.015, qty: 1 }])).toBe("1.02");
    expect(total([{ price: 1.025, qty: 1 }])).toBe("1.03"); // half-even would say 1.02
    expect(total([{ price: 2.675, qty: 1 }])).toBe("2.68"); // classic float trap
  });

  test("leaves amounts below the half-cent alone", () => {
    expect(total([{ price: 1.004, qty: 1 }])).toBe("1.00");
    expect(total([{ price: 1.0049, qty: 1 }])).toBe("1.00");
    expect(total([{ price: 1.006, qty: 1 }])).toBe("1.01");
  });

  test("rounds the line total once, not per unit", () => {
    expect(total([{ price: 0.333, qty: 3 }])).toBe("1.00"); // 0.999
    expect(total([{ price: 0.1, qty: 3 }])).toBe("0.30");   // 0.30000000000000004
    expect(total([{ price: 2.5, qty: 2 }])).toBe("5.00");   // normal case
  });

  test("sums rounded line totals", () => {
    expect(
      total([
        { price: 1.005, qty: 1 },
        { price: 0.004, qty: 1 },
      ])
    ).toBe("1.01");
  });

  test("returns 0.00 for an empty basket", () => {
    expect(total([])).toBe("0.00");
  });

  test("returns 0.00 for a zero-quantity or zero-price line", () => {
    expect(total([{ price: 1.005, qty: 0 }])).toBe("0.00");
    expect(total([{ price: 0, qty: 5 }])).toBe("0.00");
  });

  test("handles a large amount without losing the cent", () => {
    expect(total([{ price: 1234567.895, qty: 1 }])).toBe("1234567.90");
  });

  test("rejects missing or non-numeric prices", () => {
    expect(() => total([{ price: undefined, qty: 1 }])).toThrow();
    expect(() => total([{ price: "abc", qty: 1 }])).toThrow();
    expect(() => total([{ price: NaN, qty: 1 }])).toThrow();
  });

  test("rejects a fractional quantity", () => {
    expect(() => total([{ price: 1.0, qty: 1.5 }])).toThrow();
  });
});
```

Notes I'd add to the PR for a reviewer:

- **The negative case is a decision, not a test I should guess at.** `-1.005` could be `-1.01` (half away from zero) or `-1.00` (half up on magnitude). Credit notes are real money, so I've asked the owner rather than pinning one. A test will be added the moment they say which.
- **Money should not be a float.** This fix works because it rounds on the decimal string form. The durable version is integer minor units or decimal strings end-to-end. I've filed #___ rather than doing it on a bugfix branch; the tests above lock current behaviour so that refactor has a net.

